---@class OptionalGiftView : ViewBase
OptionalGiftView = class("OptionalGiftView", ViewBase)

function OptionalGiftView:initialize()
    ViewBase.initialize(self)
    ViewBase.RegisteAction(self, "OptionalGiftViewAction")
end
---@type ArticleCell
local _Data = nil
local __AddNum = -1
function OptionalGiftView:Awake()
    CommonHelper:HButtonSetCallback("BtnClose", self.gameObject, function(data)
        UIManager:Get():ClosePopup()
    end)
    CommonHelper:HButtonSetCallback("BtnClose2", self.gameObject, function(data)
        UIManager:Get():ClosePopup()
    end)
    self.selectId = -1
    self.scroll = UIUtil.GetTypeChildWightByParent("ChooseScrollView", self.gameObject, typeof(MoreRowScrollView))
    CommonHelper:HButtonSetCallback("BtnEditorRemove", self.gameObject, function(data)
        __AddNum = __AddNum - 1
        if __AddNum <= 1 then
            __AddNum = 1
        end
        self:SetUseNum()
    end)
    CommonHelper:HButtonSetCallback("BtnEditorAdd", self.gameObject, function(data)
        __AddNum = __AddNum + 1

        if __AddNum >= _Data:GetCount() then
            __AddNum = _Data:GetCount()
        end
        self:UseTip()

        self:SetUseNum()
    end)
    CommonHelper:HButtonSetCallback("BtnEditorMax", self.gameObject, function(data)
        __AddNum = _Data:GetCount()
        self:UseTip()
        self:SetUseNum()
    end)
    CommonHelper:HButtonSetCallback("BtnChoose", self.gameObject, function(data)
        if self.selectId == -1 then
            CommonTipsHelper:Get():ShowCenterTips(CommonHelper:GetTempStr_Default(TemplateStringID.OptionalGiftNotChoose))
        else

            KnapsackSubsystem:Get():SendMsg_OpenOptionalBox(self.optionalGiftId, self.selectId,__AddNum)
        end
    end)
end

function OptionalGiftView:OptionalGiftViewSetData(optionalGiftId)
    self.optionalGiftId = optionalGiftId
    self.selectId = -1
    self.selectType = -1
    _Data = KnapsackDataManager:Get():GetArticleByCfgid(optionalGiftId)
    __AddNum = 1
    self:RefreshInfo()
    self:SetUseNum()
    CommonHelper:SetInputLimitInputNum(self.buyInput,1,_Data:GetCount(),function(num)
        __AddNum=num
        self:SetUseNum()
    end)
end
function OptionalGiftView:OnClose()
    CommonHelper:ReleasePool(UIModuleID.OptionalGift)

end
function OptionalGiftView:SetUseNum()
    self.buyInput = CommonHelper:SetInputFieldText("UseNumInput", self.gameObject, __AddNum)
end
function OptionalGiftView:UseTip()
    if __AddNum > 1 and self.propType == PropType.Article then
        if self.cfg.type == KnapsackType.Type4 and self.cfg.school == KnapsackConsumeSubType.ComposeTicket then
            CommonTipsHelper:ShowCenterTips(CommonHelper:GetTempStr_Default(TemplateStringID.Shop_Compose_UserOnce))
            __AddNum = 1
        end
    end
end

function OptionalGiftView:RefreshInfo()
    local _, cfg = CommonHelper:GetPropTypeById(self.optionalGiftId)
    CommonHelper:SetText("###title", self.gameObject, CommonHelper:GetTempStr_Default(cfg.name))
    ---@type RewardData[]
    local rewards=nil

    if cfg.propstype == KnapsackType.OptionalBox then
        ---@type dictoptionalbox_config_cell
        local config = CommonHelper:GetTableDataByID(ConfigNames.dictoptionalbox_config, self.optionalGiftId)
        rewards=CommonHelper:SetDataByStrIdAndNum(config.propsids,config.propsnums)
        CommonHelper:SetGameObjectActive("BtnChoose", self.gameObject, true)
        CommonHelper:SetGameObjectActive("shownum", self.gameObject, true)
    end

    if cfg.propstype == KnapsackType.RandomBox then
        rewards = CommonHelper:GetRewardByDictDownId(cfg.propsadd)
        CommonHelper:SetGameObjectActive("BtnChoose", self.gameObject, false)
        CommonHelper:SetGameObjectActive("shownum", self.gameObject, false)
    end
    CommonHelper:InitMoreRowScrollView(self.scroll, #rewards, 5, function(dataIndex, itemObj, scroll)
        local obj = UIUtil.GetChild("ItemCom_202", itemObj)
        local param = Param_ItemArticleParam()
        param.count = rewards[dataIndex+1].num

        CommonHelper:SetItemComGroup(obj, UIModuleID.OptionalGift, rewards[dataIndex+1].id, param, function(index)
            CommonHelper:ShowPartInfoByCfgId(rewards[index].id, UIModuleID.OptionalGift, false)
        end,dataIndex+1)

        CommonHelper:HButtonSetCallback("select", itemObj, function(btnData)
            if self.selectId ~= btnData.intData then
                self.selectId = btnData.intData
            else
                self.selectId = -1
            end
            CommonHelper:MoreRowView_RefreshCurList(self.scroll,false)
        end, dataIndex)

        if cfg.propstype == KnapsackType.RandomBox then
            CommonHelper:SetGameObjectActive("select", itemObj, false)

        end
        CommonHelper:SetGameObjectActive("hover", itemObj, self.selectId == dataIndex)
    end, true)
end


